using System.Net;
using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.Hosting;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using RaceDay.Api.Data;
using Xunit;
namespace RaceDay.Tests;
public class ApiTests {
 private sealed class Factory:WebApplicationFactory<Program>{private readonly string databaseName=Guid.NewGuid().ToString(); protected override void ConfigureWebHost(IWebHostBuilder builder){builder.ConfigureServices(services=>{var old=services.SingleOrDefault(x=>x.ServiceType==typeof(DbContextOptions<RaceDayDbContext>));if(old!=null)services.Remove(old);services.AddDbContext<RaceDayDbContext>(x=>x.UseInMemoryDatabase(databaseName));});}}
 private static object Register(string role,string email)=>new{fullName="Test User",email,password="StrongPass123!",role,contactNumber="0821234567",organisationName="Test Club",dateOfBirth="1995-01-01"};
 private static async Task<HttpClient> Login(Factory factory,string role,string email){var client=factory.CreateClient(new WebApplicationFactoryClientOptions{HandleCookies=true,AllowAutoRedirect=false});var reg=await client.PostAsJsonAsync("/api/auth/register",Register(role,email));Assert.Equal(HttpStatusCode.Created,reg.StatusCode);var login=await client.PostAsJsonAsync("/api/auth/login",new{email,password="StrongPass123!"});Assert.Equal(HttpStatusCode.OK,login.StatusCode);return client;}
 private static object Event(DateTime? date=null)=>new{name="Joburg 10K",description="City run",eventDate=date??DateTime.UtcNow.AddDays(10),location="Johannesburg",distanceKm=10,eventType="Run"};
 [Fact] public async Task Registration_Login_And_Duplicate_Email(){using var f=new Factory();using var c=f.CreateClient();Assert.Equal(HttpStatusCode.Created,(await c.PostAsJsonAsync("/api/auth/register",Register("Organiser","a@test.com"))).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsJsonAsync("/api/auth/register",Register("Organiser","a@test.com"))).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await c.PostAsJsonAsync("/api/auth/login",new{email="a@test.com",password="WrongPassword"})).StatusCode);Assert.Equal(HttpStatusCode.OK,(await c.PostAsJsonAsync("/api/auth/login",new{email="a@test.com",password="StrongPass123!"})).StatusCode);}
 [Fact] public async Task Invalid_Role_Registration_Is_Rejected(){using var f=new Factory();using var c=f.CreateClient();Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsJsonAsync("/api/auth/register",Register("Admin","admin@test.com"))).StatusCode);}
 [Fact] public async Task Unauthenticated_Private_Endpoints_Return_401(){using var f=new Factory();using var c=f.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/users/me")).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await c.PostAsJsonAsync("/api/events",Event())).StatusCode);}
 [Fact] public async Task Organiser_Can_Create_And_Update_Event(){using var f=new Factory();using var c=await Login(f,"Organiser","owner@test.com");var response=await c.PostAsJsonAsync("/api/events",Event());Assert.Equal(HttpStatusCode.Created,response.StatusCode);var json=await response.Content.ReadFromJsonAsync<System.Text.Json.JsonElement>();var id=json.GetProperty("eventId").GetInt32();Assert.Equal(HttpStatusCode.OK,(await c.PutAsJsonAsync($"/api/events/{id}",Event())).StatusCode);Assert.Equal(HttpStatusCode.OK,(await c.GetAsync("/api/events/mine")).StatusCode);Assert.Equal(HttpStatusCode.NoContent,(await c.DeleteAsync($"/api/events/{id}")).StatusCode);}
 [Fact] public async Task Participant_Cannot_Manage_Events_And_Organiser_Cannot_Enrol(){using var f=new Factory();using var p=await Login(f,"Participant","participant@test.com");using var o=await Login(f,"Organiser","organiser@test.com");Assert.Equal(HttpStatusCode.Forbidden,(await p.PostAsJsonAsync("/api/events",Event())).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await o.PostAsJsonAsync("/api/events/1/enrolments",new{categoryId=1})).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await o.GetAsync("/api/participants/me/results")).StatusCode);}
 [Fact] public async Task Participant_Can_Enrol_And_Duplicate_Is_Rejected(){using var f=new Factory();using var o=await Login(f,"Organiser","owner2@test.com");using var p=await Login(f,"Participant","runner@test.com");var created=await (await o.PostAsJsonAsync("/api/events",Event())).Content.ReadFromJsonAsync<System.Text.Json.JsonElement>();var eventId=created.GetProperty("eventId").GetInt32();var catResponse=await o.PostAsJsonAsync($"/api/events/{eventId}/categories",new{name="10km Open",minAge=(int?)null,maxAge=(int?)null,distanceKm=10});Assert.Equal(HttpStatusCode.Created,catResponse.StatusCode);var cat=await catResponse.Content.ReadFromJsonAsync<System.Text.Json.JsonElement>();var catId=cat.GetProperty("categoryId").GetInt32();Assert.Equal(HttpStatusCode.Created,(await p.PostAsJsonAsync($"/api/events/{eventId}/enrolments",new{categoryId=catId})).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await p.PostAsJsonAsync($"/api/events/{eventId}/enrolments",new{categoryId=catId})).StatusCode);var entries=await (await p.GetAsync("/api/participants/me/enrolments")).Content.ReadFromJsonAsync<System.Text.Json.JsonElement>();Assert.Equal(1,entries.GetArrayLength());Assert.Equal(HttpStatusCode.OK,(await o.GetAsync($"/api/events/{eventId}/enrolments")).StatusCode);}
 [Fact] public async Task Other_Organiser_Cannot_Edit_Another_Organisers_Event(){using var f=new Factory();using var first=await Login(f,"Organiser","first@test.com");using var second=await Login(f,"Organiser","second@test.com");var created=await (await first.PostAsJsonAsync("/api/events",Event())).Content.ReadFromJsonAsync<System.Text.Json.JsonElement>();var id=created.GetProperty("eventId").GetInt32();Assert.Equal(HttpStatusCode.Forbidden,(await second.PutAsJsonAsync($"/api/events/{id}",Event())).StatusCode);}
 [Fact] public async Task Logout_Ends_Session(){using var f=new Factory();using var c=await Login(f,"Participant","logout@test.com");Assert.Equal(HttpStatusCode.OK,(await c.PostAsync("/api/auth/logout",null)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/users/me")).StatusCode);}
 [Fact] public async Task Bad_Event_Data_Is_Rejected(){using var f=new Factory();using var c=await Login(f,"Organiser","bad@test.com");Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsJsonAsync("/api/events",new{name="Race",eventDate=DateTime.UtcNow.AddDays(2),location="Joburg",distanceKm=-5,eventType="Swim"})).StatusCode);}
}
